.huw-musical *{box-sizing:border-box}
.huw-musical-layout{display:grid;grid-template-columns:minmax(0,1.6fr) minmax(290px,1fr);gap:0}
.huw-musical-stage{background:var(--musical-bg);color:#f6e8cd;padding:16px;min-width:0}
.huw-musical-score{background:#fffdf7;padding:16px;min-width:0;max-height:540px;overflow:auto}
.huw-musical-subtitle{font-size:14px;margin:0 0 8px;font-weight:650;letter-spacing:.04em}
.huw-musical-canvas{overflow:hidden;border-radius:10px;background:#0d1423}
.huw-musical-canvas svg{display:block;width:100%;height:auto;aspect-ratio:16/9}
.huw-musical-paper svg{max-width:100%;height:auto}
.huw-musical-transport{display:flex;align-items:center;flex-wrap:wrap;gap:10px;padding:14px 16px;background:#e6edf0}
.huw-musical-transport button,.huw-musical-shots button{cursor:pointer;border:1px solid #879fa9;background:#fff;border-radius:8px;padding:8px 12px;font:inherit}
.huw-musical-transport button:disabled{opacity:.45;cursor:wait}
.huw-musical-play{background:#174b62!important;color:white;border-color:#174b62!important;min-width:106px}
.huw-musical-range{flex:1 1 150px;accent-color:#136f87}
.huw-musical-time{font-variant-numeric:tabular-nums;white-space:nowrap}
.huw-musical-speed{padding:8px;border-radius:8px;background:white;border:1px solid #879fa9}
.huw-musical-status{margin:0;padding:0 16px 10px;font-size:13px;color:#49616b}
.huw-musical-error{color:#a23a31}
.huw-musical-shots{display:flex;flex-wrap:wrap;align-items:center;gap:7px;padding:8px 16px 14px}
.huw-musical-shot{border:1px solid #98abb0;background:#fff;padding:6px 9px;border-radius:20px;font:inherit;cursor:pointer}
.huw-musical-links{display:flex;flex-wrap:wrap;gap:20px;padding:0 16px 16px;font-size:13px}
.huw-musical-native{display:none}
@media(max-width:800px){.huw-musical-layout{grid-template-columns:1fr}.huw-musical-score{max-height:330px}}

/* Musical Studio: notation follow and the CutOut/ABC composition timeline */
.huw-musical-note-active,.huw-musical-note-active path,.huw-musical-note-active ellipse{fill:#d35216!important;stroke:#b93112!important}
.huw-musical-note-cursor{stroke:#db582a;stroke-width:2.5;pointer-events:none}
.huw-musical-active-camera{margin-left:auto;font-size:13px;color:#365c6e;font-weight:650}
.huw-musical-editor{border-top:1px solid #b5c6cf;background:#f8fafb;padding:14px 16px 18px;overflow:hidden}
.huw-musical-editor-header{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.huw-musical-editor h3{margin:0;font-size:18px}
.huw-musical-editor>p{margin:7px 0 13px;color:#506777;font-size:13px}
.huw-musical-tracks{max-height:430px;overflow:auto;border:1px solid #b9cbd5;background:white;border-radius:11px}
.huw-musical-track{display:grid;grid-template-columns:minmax(130px,195px) minmax(0,1fr);min-height:36px;border-bottom:1px solid #e0e8ed}
.huw-musical-track:last-child{border-bottom:0}.huw-musical-track.is-selected{background:#eef8fc}
.huw-musical-lane-title{font-size:12px;font-weight:600;display:flex;align-items:center;min-width:0;padding:5px 9px;border-right:1px solid #d3dfe6;cursor:pointer;overflow:hidden;text-overflow:ellipsis}
.huw-musical-lane{position:relative;cursor:crosshair;min-width:0;min-height:35px;background:repeating-linear-gradient(90deg,transparent 0,transparent calc(12.5% - 1px),#e5e9ee calc(12.5% - 1px),#e5e9ee 12.5%)}
.huw-musical-lane-cursor{position:absolute;left:0;top:0;bottom:0;width:2px;background:#e05238;pointer-events:none;z-index:3}
.huw-musical-block{position:absolute;left:1%;right:1%;top:8px;height:19px;background:#91bacb;border-radius:5px;color:#183e4e;font-size:10px;white-space:nowrap;overflow:hidden;padding-left:7px;pointer-events:none}
.huw-musical-key{position:absolute;top:10px;left:0;transform:translateX(-50%);width:13px;height:13px;border:1px solid #2f6877;border-radius:3px;background:#b7e5f2;rotate:45deg;z-index:2;cursor:ew-resize;padding:0;touch-action:none}
.huw-musical-key.is-selected{background:#f4ac45;border:2px solid #8b4421;z-index:4}
.huw-musical-inspector{display:flex;flex-wrap:wrap;align-items:end;gap:8px 14px;padding-top:13px}
.huw-musical-inspector>strong{flex-basis:100%;font-size:13px}
.huw-musical-inspector>p{font-size:13px;margin:0}
.huw-musical-key-actions{display:flex;gap:6px}
.huw-musical-inspector button{border:1px solid #8ea8b4;background:#fff;padding:6px 11px;border-radius:7px;cursor:pointer;font:inherit;font-size:12px}
.huw-musical-inspector button:disabled{opacity:.45;cursor:not-allowed}
.huw-musical-property{display:flex;flex-direction:column;gap:3px;font-size:12px;font-weight:600}
.huw-musical-property input,.huw-musical-property select{width:104px;max-width:100%;border:1px solid #a0b4bd;border-radius:6px;padding:5px;background:white;font:inherit}
.huw-musical-edited-status{display:block;min-height:17px;margin-top:8px;font-size:12px;color:#2f6d52}
@media(max-width:580px){.huw-musical-track{grid-template-columns:125px minmax(0,1fr)}.huw-musical-inspector{gap:10px}}

.huw-musical-score-page[hidden]{display:none!important}
.huw-musical-song-clip{position:absolute;top:6px;height:23px;min-width:2px;padding:2px 6px;border-radius:5px;background:#4f99b4;color:#fff;border:1px solid #2b617f;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left;cursor:pointer;z-index:2}
.huw-musical-song-clip:nth-child(2n){background:#8265b8;border-color:#5d4791}
.huw-musical-song-clip.is-selected{outline:2px solid #f09b25;outline-offset:-2px}
.huw-musical-song-actions{flex-wrap:wrap}
.huw-musical-song-select{max-width:260px;min-width:120px;padding:6px;border-radius:6px;border:1px solid #9bb0bf}
.huw-musical-song-info{font-size:12px!important;color:#43566b;margin:0}

.huw-musical-song-clip{box-sizing:border-box;position:absolute;top:5px;height:25px;min-width:3px;border-radius:5px;padding:3px 6px;background:#29788f;color:#fff;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:left;cursor:grab;z-index:2;user-select:none;touch-action:none}
.huw-musical-song-clip:nth-child(odd){background:#6a5693}
.huw-musical-song-clip.is-selected{box-shadow:inset 0 0 0 2px #f6c35b}
.huw-musical-fade-in,.huw-musical-fade-out{pointer-events:none;position:absolute;top:0;bottom:0}
.huw-musical-fade-in{left:0;background:linear-gradient(115deg,rgba(0,0,0,.65),rgba(255,255,255,.08))}
.huw-musical-fade-out{right:0;background:linear-gradient(65deg,rgba(255,255,255,.08),rgba(0,0,0,.65))}
.huw-musical-fade-handle{position:absolute;top:2px;bottom:2px;width:7px;border:1px solid #fff;border-radius:3px;background:#f6c35b;cursor:ew-resize;z-index:4}
.huw-musical-fade-left{left:0}.huw-musical-fade-right{right:0}
.huw-musical-mute{flex-direction:row;align-items:center}
.huw-musical-mute input{width:auto}
.huw-musical-score-label{font-size:12px;font-weight:bold;color:#3a5570;background:#f1f6f9;padding:5px 8px;margin:0 0 7px;border-radius:5px}
.huw-musical-score-page[hidden]{display:none!important}
"},"$:/plugins/huwiki/musical/README":{"title":"$:/plugins/huwiki/musical/README","type":"text/vnd.tiddlywiki","text":"! Musical Edition – CutOut + ABC

Musical Studio har én afspiller til musik, levende nodeark, animation, belysning og kamera. Musiksporet indeholder hele ABC-musiknumre – ikke separate instrumentspor.

**Musiknumre:** Vælg et komplet ABC-nodeark på tidslinjen. Indsæt, slet eller flyt det i rækkefølgen. Numrene afspilles efter hinanden; hvert nummer har sin egen lydmotor, notation og lokale nodecursor. Tidslinjen og kameraet bruger samlet absolut tid.

**Scenografi:** Separate spor til baggrund, scene, forgrund, musikerne og belysning. To uafhængige virtuelle kameraer og et klippespor. Flyt, indsæt eller redigér kontrolpunkter. Data gemmes i de eksisterende CutOut-tiddlere.

**English:** One transport for multiple complete ABC songs, live score, animation and two editable cameras. Songs play in sequence. Score voices are not separate song clips.

**Begrænsninger:** Ingen samtidige musiknumre, crossfade eller MP4-eksport. Skift mellem numre kan medføre kort indlæsning af lyd. Kameraets og animationernes præcision, især på Safari/iPad, skal afprøves med rigtig lyd.
"},"$:/plugins/huwiki/musical/editor.js":{"title":"$:/plugins/huwiki/musical/editor.js","type":"application/javascript","module-type":"library","text":"/*\
